13	/** Why a pass did not go green. The next pass gets it in its brief. */
14	export type Failure =
15	  | { kind: 'silence'; detail: string }
16	  | { kind: 'check'; cmd: string; code: number; tail: string }
17	  | { kind: 'grade'; lines: Array<{ card: string; score: number; gap: string; person?: true }> }
