27	   *  merged in, and these are the files git left conflicted, maybe none
28	   *  (#st-build-conflict-resolve). Without it, the pass starts fresh from the tip. */
29	  | { kind: 'merge'; cmd: string; code: number; tail: string; conflict?: boolean; resolving?: string[] }
