31	/** Which gate failed a pass, with what the report groups it by — #ms-fail. */
32	export type GateDetail =
33	  | { gate: 'check' | 'merge'; name: string }
34	  | { gate: 'grader'; cards: string[] }
35	  | { gate: 'review'; findings: Array<{ area: string; severity: string }> }
36	  | { gate: 'step'; name: string }
37	  | { gate: 'looping' | 'silence' | 'died' }
38	
39	export function gateOf(f: Failure): GateDetail {
40	  switch (f.kind) {
41	    case 'check':
42	    case 'merge':
43	      return { gate: f.kind, name: f.cmd }
44	    case 'grade':
45	      return { gate: 'grader', cards: f.lines.map((l) => l.card) }
46	    case 'review':
47	      return { gate: 'review', findings: f.findings.map((x) => ({ area: x.area, severity: x.severity })) }
48	    case 'step':
49	      return { gate: 'step', name: f.step }
50	    case 'looping':
51	    case 'silence':
52	    case 'died':
53	      return { gate: f.kind }
54	  }
55	}
